# This script is generated by AI
# Used by filter out the result in LC.log
import os
import glob
import re

def find_graphanalytics_dirs():
    """Find all subdirectories that start with 'GraphAnalytics'"""
    graphanalytics_dirs = []
    
    # Look for directories starting with "GraphAnalytics"
    for item in os.listdir('.'):
        if os.path.isdir(item) and item.startswith('GraphAnalytics'):
            graphanalytics_dirs.append(item)
    
    # Also check for the hyphenated version you showed in your structure
    for item in os.listdir('.'):
        if os.path.isdir(item) and item.startswith('Graph-Analytics'):
            graphanalytics_dirs.append(item)
    
    return sorted(graphanalytics_dirs)

def extract_running_time(file_path):
    """Extract running time from LC.log file"""
    try:
        with open(file_path, 'r') as f:
            content = f.read()
            # Search for "Running time = number" pattern
            match = re.search(r'Running time\s*=\s*(\d+)', content)
            if match:
                return int(match.group(1))
    except (FileNotFoundError, PermissionError, UnicodeDecodeError) as e:
        print(f"Warning: Could not read {file_path}: {e}")
    return None

def main():
    # Find all GraphAnalytics directories automatically
    base_dirs = find_graphanalytics_dirs()
    
    if not base_dirs:
        print("No directories starting with 'GraphAnalytics' found!")
        return
    
    print(f"Found GraphAnalytics directories: {base_dirs}")
    
    # Define all possible BE types based on your directory structure
    be_types = [
        "400.perlbench", "401.bzip2", "403.gcc", "429.mcf", 
        "445.gobmk", "456.hmmer", "458.sjeng", "462.libquantum",
        "464.h264ref", "470.lbm", "473.astar", "483.xalancbmk"
    ]
    
    # Dictionary to store results: {lc_type: {be_type: running_time}}
    results = {}
    
    # Collect all running times
    for lc_dir in base_dirs:
        results[lc_dir] = {}
        
        for be_type in be_types:
            lc_log_path = os.path.join(lc_dir, be_type, "LC.log")
            if os.path.exists(lc_log_path):
                running_time = extract_running_time(lc_log_path)
                results[lc_dir][be_type] = running_time
                print(f"Found: {lc_dir}/{be_type}/LC.log -> {running_time}")
            else:
                results[lc_dir][be_type] = None
                print(f"Missing: {lc_dir}/{be_type}/LC.log")
    
    # Create and display the table
    print("\n" + "=" * 80)
    print("Running Time Results Table")
    print("=" * 80)
    
    # Header row
    header = "LC Type".ljust(30)
    for be_type in be_types:
        # Shorten BE type names for better display
        short_name = be_type.replace("400.", "").replace("401.", "").replace("403.", "").replace("429.", "").replace("445.", "").replace("456.", "").replace("458.", "").replace("462.", "").replace("464.", "").replace("470.", "").replace("473.", "").replace("483.", "")
        header += short_name.ljust(12)
    print(header)
    print("-" * 80)
    
    # Data rows
    for lc_dir in base_dirs:
        row = lc_dir.ljust(30)
        for be_type in be_types:
            running_time = results[lc_dir].get(be_type, None)
            if running_time is not None:
                row += str(running_time).ljust(12)
            else:
                row += "N/A".ljust(12)
        print(row)
    
    # Create CSV file for easier analysis
    csv_filename = "running_times.csv"
    with open(csv_filename, 'w') as f:
        # Write header
        f.write("LC_Type," + ",".join(be_types) + "\n")
        
        # Write data
        for lc_dir in base_dirs:
            row = [lc_dir]
            for be_type in be_types:
                running_time = results[lc_dir].get(be_type, None)
                row.append(str(running_time) if running_time is not None else "N/A")
            f.write(",".join(row) + "\n")
    
    print(f"\n✓ CSV file '{csv_filename}' has been created!")
    print(f"✓ The file contains {len(base_dirs)} LC types and {len(be_types)} BE benchmarks")

if __name__ == "__main__":
    main()